-- =========================================================
-- Catalogue CS2 sur le modèle de Hellcase (HENC-57)
-- =========================================================
-- Généré par un script : noms, grades et images des skins issus du jeu de
-- données public ByMykel/CSGO-API (images hébergées par Steam), prix estimés
-- en crédits (1 crédit = 0,01 €). Probabilités calculées pour que chaque
-- caisse totalise 100 000 et rende en moyenne ~88 % de son prix.

-- Usure (FN, MW, FT, WW, BS) et StatTrak™ de chaque skin
ALTER TABLE items ADD COLUMN exterior TEXT CHECK (exterior IN ('FN', 'MW', 'FT', 'WW', 'BS'));
ALTER TABLE items ADD COLUMN stattrak BOOLEAN NOT NULL DEFAULT false;

-- Ordre d'affichage des sections du catalogue
ALTER TABLE case_categories ADD COLUMN position INT NOT NULL DEFAULT 0;

UPDATE case_categories SET name = 'HeavenCases', slug = 'heavencases', position = 1
WHERE id = '00000000-0000-4000-8000-000000000001';

-- Les anciennes tables de butin des caisses de démo sont remplacées.
DELETE FROM case_items WHERE case_id IN (
    '00000000-0000-4000-8000-000000000201',
    '00000000-0000-4000-8000-000000000202',
    '00000000-0000-4000-8000-000000000203');

-- Skins : les ids 101 à 110 existent déjà (objets de démo), les autres sont créés.
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, rarity = EXCLUDED.rarity, value = EXCLUDED.value,
    category = EXCLUDED.category, image_url = EXCLUDED.image_url, exterior = EXCLUDED.exterior,
    stattrak = EXCLUDED.stattrak;

-- Caisses : 201 à 203 existent déjà, les autres sont créées. Pas de description.
ON CONFLICT (id) DO UPDATE SET name = EXCLUDED.name, slug = EXCLUDED.slug, price = EXCLUDED.price,
    category_id = EXCLUDED.category_id, description = NULL;


